<?php
require_once __DIR__ . '/../config/auth.php';
require_student();
$emailStmt=db()->prepare('SELECT email FROM users WHERE id=?');$emailStmt->execute([$_SESSION['student_id']]);$email=$emailStmt->fetchColumn();
$stmt=db()->prepare('SELECT a.*,c.name AS course,d.name AS department FROM applications a JOIN courses c ON c.id=a.course_id JOIN departments d ON d.id=c.department_id WHERE a.email=? ORDER BY a.created_at DESC LIMIT 1');$stmt->execute([$email]);$application=$stmt->fetch();
$ns=db()->prepare('SELECT title,message,created_at,is_read FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 8');$ns->execute([$_SESSION['student_id']]);$notifications=$ns->fetchAll();
$pageTitle='Student dashboard';include __DIR__.'/../includes/header.php';
?><section class="page-hero"><div class="container"><p class="eyebrow">Student portal</p><h1>Welcome, <?= e($_SESSION['student_name']) ?>.</h1><p>Your application and student services at a glance.</p></div></section><section class="content-section container"><div class="dashboard-grid"><div class="content-panel"><h2>My application</h2><?php if($application):?><div class="result-list"><div class="result-row"><strong>Application number</strong><span><?= e($application['application_number']) ?></span></div><div class="result-row"><strong>Course</strong><span><?= e($application['course']) ?></span></div><div class="result-row"><strong>Department</strong><span><?= e($application['department']) ?></span></div><div class="result-row"><strong>Status</strong><span class="badge"><?= e($application['status']) ?></span></div></div><div class="quick-actions" style="margin-top:18px"><a class="button" href="<?= e(url('student/application-status.php?number=' . rawurlencode($application['application_number']))) ?>">Application status</a><a class="button button-outline" href="<?= e(url('student/documents.php')) ?>">Documents</a><?php if($application['status']==='Accepted'):?><a class="button" href="<?= e(url('student/admission.php?id=' . (int)$application['id'])) ?>">View admission letter</a><?php endif;?></div><?php else:?><p>You do not have an application linked to this account yet.</p><a class="button" href="<?= e(url('apply.php')) ?>">Apply now</a><?php endif;?></div><div class="content-panel"><h2>Student services</h2><div class="status-list"><div><span>Profile</span><a class="text-link" href="<?= e(url('student/profile.php')) ?>">Update <span>→</span></a></div><div><span>Documents</span><a class="text-link" href="<?= e(url('student/documents.php')) ?>">Manage <span>→</span></a></div><div><span>Downloads</span><a class="text-link" href="<?= e(url('downloads.php')) ?>">Open <span>→</span></a></div><div><span>Support</span><a class="text-link" href="<?= e(url('contact.php')) ?>">Contact <span>→</span></a></div></div></div><div class="content-panel full-width"><h2>Notifications</h2><?php foreach($notifications as $note):?><article class="faq-item"><h3><?= e($note['title']) ?></h3><p><?= e($note['message']) ?> · <?= e(date('d M Y',strtotime($note['created_at']))) ?></p></article><?php endforeach;?><?php if(!$notifications):?><p class="empty-state">You’re all caught up.</p><?php endif;?></div></section><?php include __DIR__.'/../includes/footer.php';?>